class Solution {
    private int waviness(long x) {
        String s = Long.toString(x);
        if (s.length() < 3) return 0;
        int w = 0;
        for (int i = 1; i < s.length() - 1; i++) {
            int p = s.charAt(i - 1) - '0';
            int c = s.charAt(i) - '0';
            int n = s.charAt(i + 1) - '0';
            if ((c > p && c > n) || (c < p && c < n)) w++;
        }
        return w;
    }

    public long totalWavinessII(long low, long high) {
        long total = 0;
        for (long x = low; x <= high; x++) {
            total += waviness(x);
        }
        return total;
    }
}

